script:
var doc = Document;
// Goal: a 20 x 20 ft floor slab on the lowest level, of a named floor type when it exists.

// 1. Level and floor type. Type lookup by Name is template-dependent, so fall back to the
//    document's default floor type (GetDefaultFloorType(doc, isFoundation: false)) when the
//    name is absent rather than failing.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) { if (level == null || l.Elevation < level.Elevation) level = l; }
string wantedTypeName = "Generic 12\"";
Autodesk.Revit.DB.ElementId floorTypeId = null;
foreach (Autodesk.Revit.DB.FloorType ft in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.FloorType))) {
  if (ft.Name == wantedTypeName && !ft.IsFoundationSlab) { floorTypeId = ft.Id; break; }
}
var usedDefault = floorTypeId == null;
if (usedDefault) { floorTypeId = Autodesk.Revit.DB.Floor.GetDefaultFloorType(doc, false); }

return Connector.WithTransaction(doc, () => {
  // 2. The footprint as ONE closed, planar CurveLoop: each segment starts where the previous ended
  //    and the last returns to the first point. An open loop throws at Floor.Create.
  var pts = new[] { new Autodesk.Revit.DB.XYZ(0, 0, 0), new Autodesk.Revit.DB.XYZ(20, 0, 0), new Autodesk.Revit.DB.XYZ(20, 20, 0), new Autodesk.Revit.DB.XYZ(0, 20, 0) };
  var loop = new Autodesk.Revit.DB.CurveLoop();
  for (int i = 0; i < pts.Length; i++) { loop.Append(Autodesk.Revit.DB.Line.CreateBound(pts[i], pts[(i + 1) % pts.Length])); }
  var profile = new System.Collections.Generic.List<Autodesk.Revit.DB.CurveLoop> { loop };

  // 3. Floor.Create(doc, loops, typeId, levelId) is the 2022+ API; the older
  //    Document.Create.NewFloor(CurveArray, ...) overloads are obsolete. The loop's Z is ignored:
  //    the slab sits at the level's elevation (plus the type's offset).
  var floor = Autodesk.Revit.DB.Floor.Create(doc, profile, floorTypeId, level.Id);
  doc.Regenerate();

  // 4. Verify: the floor is on the level and its area equals the footprint's (400 sq ft here).
  var areaParam = floor.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.HOST_AREA_COMPUTED);
  double area = areaParam != null ? areaParam.AsDouble() : 0.0;
  return new { floorId = floor.Id.Value, floorType = doc.GetElement(floorTypeId).Name, usedDefaultType = usedDefault, onLevel = floor.LevelId == level.Id, areaSqFt = area, areaMatches = System.Math.Abs(area - 400.0) < 0.5 };
});
